#include <iostream>
using namespace std;

// The only language difference: default access (struct = public, class = private)
struct S { int x = 1; };
class C {
    int x = 2;                       // private by default
public:
    int get() const { return x; }
};
struct DS : S {};                    // struct inherits publicly by default
class DC : C {};                     // class inherits privately by default

struct Point { int x; int y; };      // aggregate: no ctors, no private data

int main() {
    S s;
    C c;
    DS ds;
    cout << "struct member s.x = " << s.x << "\n";
    cout << "class member via getter = " << c.get() << "\n";
    cout << "public base reached through DS: " << ds.x << "\n";
    // DC dc; dc.get();  would not compile: private inheritance hides get()
    DC dc; (void)dc;
    Point p{.x = 3, .y = 4};         // C++20 designated initializers
    cout << "Point = (" << p.x << ", " << p.y << ")\n";
}

#include <iostream>
#include <stdexcept>
using namespace std;

// Invariant: balance never goes below 0. Only member functions touch it.
class Account {
    long cents = 0;                      // private: callers cannot break the rule
public:
    void deposit(long c) {
        if (c <= 0) throw invalid_argument("deposit must be positive");
        cents += c;
    }
    bool withdraw(long c) {
        if (c <= 0 || c > cents) return false;   // refuse instead of going negative
        cents -= c;
        return true;
    }
    long balance() const { return cents; }
};

int main() {
    Account a;
    a.deposit(500);
    cout << "after deposit 500: " << a.balance() << "\n";
    cout << "withdraw 200: " << (a.withdraw(200) ? "ok" : "refused")
         << ", balance " << a.balance() << "\n";
    cout << "withdraw 900: " << (a.withdraw(900) ? "ok" : "refused")
         << ", balance " << a.balance() << "\n";
    // a.cents = -5;   // compile error: cents is private
    try { a.deposit(-1); } catch (const exception& e) { cout << "error: " << e.what() << "\n"; }
}

#include <iostream>
using namespace std;

struct Tracer {
    const char* name;
    Tracer(const char* n) : name(n) { cout << "  construct " << name << "\n"; }
    ~Tracer() { cout << "  destroy   " << name << "\n"; }
};
struct Base : Tracer { Base() : Tracer("Base") {} };

struct Derived : Base {
    Tracer m1{"member m1"};      // members are built in DECLARATION order
    Tracer m2{"member m2"};
    Derived() { cout << "  Derived body\n"; }
    ~Derived() { cout << "  ~Derived body\n"; }
};

int main() {
    cout << "enter scope\n";
    {
        Tracer a("local a");
        Derived d;               // base first, then members, then body
        Tracer b("local b");
        cout << "leaving scope\n";
    }                            // destruction is the exact reverse
    cout << "done\n";
}

#include <iostream>
#include <string>
using namespace std;

struct Noisy {
    Noisy()            { cout << "  Noisy default\n"; }
    Noisy(int v)       { cout << "  Noisy(" << v << ")\n"; }
    Noisy& operator=(int v) { cout << "  Noisy assign " << v << "\n"; return *this; }
};
struct BodyAssign { Noisy n; BodyAssign(int v) { n = v; } };   // 2 steps
struct ListInit   { Noisy n; ListInit(int v) : n(v) {} };      // 1 step

// const and reference members MUST use the list
struct Fixed {
    const int id;
    int& ref;
    Fixed(int i, int& r) : id(i), ref(r) {}
};
// Trap: init order follows declaration (a, then b), not the list order
struct Trap { int a; int b; Trap() : b(5), a(b * 2) {} };

int main() {
    cout << "body assign:\n"; BodyAssign x(1);
    cout << "list init:\n";   ListInit y(1);
    int v = 9;
    Fixed f(3, v);
    cout << "Fixed id=" << f.id << " ref=" << f.ref << "\n";
    Trap t;
    cout << "Trap b=" << t.b << " (a is garbage: it read b before b was set)\n";
}

#include <iostream>
#include <type_traits>
using namespace std;

class Counter {
    int n = 0;
public:
    // non-const member: this is Counter*; returning *this allows chaining
    Counter& add(int k) {
        static_assert(is_same_v<decltype(this), Counter*>);
        n += k;
        return *this;
    }
    // const member: this is const Counter*, so n cannot be changed here
    int get() const {
        static_assert(is_same_v<decltype(this), const Counter*>);
        return n;
    }
    bool same(const Counter& o) const { return this == &o; }   // self check
    static int twice(int v) { return v * 2; }   // static: no this at all
};

int main() {
    Counter c;
    c.add(2).add(3).add(10);          // each call returns the same object
    cout << "chained total = " << c.get() << "\n";
    Counter d;
    cout << "same as itself: " << c.same(c) << ", same as d: " << c.same(d) << "\n";
    cout << "static call without object: " << Counter::twice(21) << "\n";
}

#include <iostream>
using namespace std;

class Temperature {
    double celsius;
    explicit Temperature(double c) : celsius(c) {}
    inline static int created = 0;                 // one copy shared by all objects
public:
    static constexpr double ABS_ZERO = -273.15;    // class-wide constant
    // named constructors (factories): static, so no object is needed to call them
    static Temperature fromCelsius(double c)    { ++created; return Temperature(c); }
    static Temperature fromFahrenheit(double f) { ++created; return Temperature((f - 32) * 5 / 9); }
    static int count() { return created; }         // static function reads static data
    double c() const { return celsius; }
};

// Meyers singleton: function-local static, built on first use
struct Config {
    static Config& instance() { static Config cfg; return cfg; }
    int level = 1;
};

int main() {
    cout << "objects before: " << Temperature::count() << "\n";
    Temperature a = Temperature::fromCelsius(25);
    Temperature b = Temperature::fromFahrenheit(212);
    cout << "25C = " << a.c() << ", 212F = " << b.c() << " C\n";
    cout << "objects created: " << Temperature::count() << ", sizeof(Temperature)=" << sizeof(Temperature) << "\n";
    Config::instance().level = 5;
    cout << "same singleton level: " << Config::instance().level << "\n";
}

#include <iostream>
using namespace std;

class Counter {
public:
    // C++17: inline static is a definition. The header can hold it,
    // and the linker merges the copies from every .cpp file.
    inline static int count = 0;
    // Before C++17 you wrote only 'static int count;' here and then,
    // in exactly one .cpp file:  int Counter::count = 0;
    // Forgetting that gives: undefined reference to `Counter::count'
    static constexpr int LIMIT = 3;   // constexpr statics are implicitly inline

    Counter()  { ++count; }
    ~Counter() { --count; }
};

// Taking a reference to LIMIT needs a definition: legal here only because it is inline
const int& limitRef() { return Counter::LIMIT; }

int main() {
    cout << "start: " << Counter::count << "\n";
    {
        Counter a, b;
        cout << "two alive: " << Counter::count << "\n";
    }
    cout << "after scope: " << Counter::count << "\n";
    cout << "limit by reference: " << limitRef() << "\n";
}

#include <iostream>
#include <type_traits>
using namespace std;

class Base {
public:    int pub = 1;
protected: int prot = 2;
private:   int priv = 3;     // inherited (takes memory) but never accessible
};

class PublicD    : public Base    { public: int peek() { return prot; } };  // is-a
class ProtectedD : protected Base { public: int peek() { return prot; } };
class PrivateD   : private Base   { public: int peek() { return pub + prot; } }; // implemented-in-terms-of

int main() {
    // Can outside code treat a Derived* as a Base*?
    cout << boolalpha;
    cout << "public    upcast allowed: " << is_convertible_v<PublicD*, Base*> << "\n";
    cout << "protected upcast allowed: " << is_convertible_v<ProtectedD*, Base*> << "\n";
    cout << "private   upcast allowed: " << is_convertible_v<PrivateD*, Base*> << "\n";

    PublicD d;
    cout << "d.pub from outside (public inheritance): " << d.pub << "\n";
    // ProtectedD p; p.pub;   // error: pub became protected
    PrivateD q;
    cout << "private derived uses base inside: " << q.peek() << "\n";
    cout << "sizeof(PublicD) = " << sizeof(PublicD) << " (priv still occupies space)\n";
}

#include <iostream>
#include <string>
using namespace std;

class Animal {
    string name;
    int legs;
public:
    Animal(string n, int l) : name(n), legs(l) { cout << "Animal(" << name << "," << legs << ")\n"; }
    void show() const { cout << name << " has " << legs << " legs\n"; }
};

class Dog : public Animal {
    string breed;
public:
    // Base is named in the initializer list; it is always built first
    Dog(string n) : Animal(n, 4), breed("mixed") { cout << "Dog body, breed " << breed << "\n"; }
};

class Bird : public Animal {
public:
    using Animal::Animal;            // inherit all base constructors
};

// class Bad : public Animal { public: Bad() {} };
// error: Animal has no default constructor, so Bad() cannot compile

int main() {
    Dog d("Rex");
    d.show();
    Bird b("Tweety", 2);             // uses the inherited constructor
    b.show();
}

#include <iostream>
#include <string>
using namespace std;

struct Base {
    void print(int x)           { cout << "Base::print(int) " << x << "\n"; }
    void print(const string& s) { cout << "Base::print(string) " << s << "\n"; }
};

struct Hiding : Base {
    void print(double d) { cout << "Hiding::print(double) " << d << "\n"; }
    // Declaring ANY print here hides ALL Base::print overloads
};

struct Fixed : Base {
    using Base::print;                 // bring the base overloads back into scope
    void print(double d) { cout << "Fixed::print(double) " << d << "\n"; }
};

int main() {
    Hiding h;
    h.print(42);                       // picks print(double): int converts, base int overload is hidden
    h.Base::print(42);                 // explicit qualification reaches the hidden one
    Fixed f;
    f.print(42);                       // exact match print(int) from the base
    f.print(2.5);                      // derived overload
    f.print(string("hi"));             // base string overload is visible again
}

#include <iostream>
using namespace std;

class Secret {
    int code;
    friend class Auditor;                       // a friend class: all members get access
    friend ostream& operator<<(ostream& os, const Secret& s);   // friend function
public:
    explicit Secret(int c) : code(c) {}
};

// not a member: no this pointer, called with normal syntax, but it may read s.code
ostream& operator<<(ostream& os, const Secret& s) {
    return os << "Secret(" << s.code << ")";
}

class Auditor {
public:
    static int read(const Secret& s) { return s.code; }   // allowed by friendship
};

// A friend of Secret is NOT automatically trusted by Auditor's friends, and
// friendship is not inherited and not mutual: Secret cannot touch Auditor's private data.

int main() {
    Secret s(1234);
    cout << s << "\n";                          // uses the friend operator<<
    cout << "auditor sees code " << Auditor::read(s) << "\n";
}

#include <iostream>
using namespace std;

struct Money {
    int cents;
    Money(int c = 0) : cents(c) {}            // non-explicit: int converts to Money

    Money& operator+=(const Money& o) { cents += o.cents; return *this; }   // member

    // Non-member hidden friend: BOTH operands may be converted
    friend Money operator+(Money a, const Money& b) { return a += b; }
};

struct BadMoney {
    int cents;
    BadMoney(int c = 0) : cents(c) {}
    BadMoney operator+(const BadMoney& o) const { return BadMoney(cents + o.cents); }
};

int main() {
    Money x(50);
    cout << "x + 2 = " << (x + 2).cents << "\n";   // 2 converts to Money
    cout << "2 + x = " << (2 + x).cents << "\n";   // left side converts too
    BadMoney y(50);
    cout << "bad: y + 2 = " << (y + 2).cents << "\n";
    // (2 + y)  does not compile: int has no operator+(BadMoney), and the left
    // operand of a member operator is never converted
}

#include <iostream>
using namespace std;

struct Empty {};                       // no data: still needs a unique address
struct HasInt { int x; };
struct WithEmptyMember { Empty e; int x; };           // empty member costs padding
struct WithEmptyBase : Empty { int x; };              // empty base optimization
struct WithAttr { [[no_unique_address]] Empty e; int x; };   // C++20 for members

struct Padded  { char a; int b; char c; };   // 1 + 3 pad + 4 + 1 + 3 pad
struct Reorder { int b; char a; char c; };   // 4 + 1 + 1 + 2 pad

int main() {
    Empty e1, e2;
    cout << "sizeof(Empty)           = " << sizeof(Empty) << "\n";
    cout << "two objects differ       : " << (&e1 != &e2) << "\n";
    cout << "sizeof(HasInt)          = " << sizeof(HasInt) << "\n";
    cout << "sizeof(WithEmptyMember) = " << sizeof(WithEmptyMember) << "\n";
    cout << "sizeof(WithEmptyBase)   = " << sizeof(WithEmptyBase) << "\n";
    cout << "sizeof(WithAttr)        = " << sizeof(WithAttr) << " (gcc/clang)\n";
    cout << "sizeof(Padded)  = " << sizeof(Padded) << "\n";
    cout << "sizeof(Reorder) = " << sizeof(Reorder) << "\n";
}

#include <atomic>
#include <iostream>
using namespace std;

class Widget {
    long id;
    inline static atomic<long> nextId{1};      // atomic: safe if threads create widgets
    inline static atomic<int>  alive{0};
public:
    Widget() : id(nextId.fetch_add(1)) { ++alive; }
    // The default copy would copy the id and skip the counter: write it ourselves
    Widget(const Widget&) : id(nextId.fetch_add(1)) { ++alive; }   // a copy is a NEW object
    Widget& operator=(const Widget&) { return *this; }             // identity never changes
    ~Widget() { --alive; }

    long getId() const { return id; }
    static int aliveCount() { return alive.load(); }
};

int main() {
    Widget a;
    Widget b;
    cout << "a.id=" << a.getId() << " b.id=" << b.getId() << " alive=" << Widget::aliveCount() << "\n";
    {
        Widget c = a;                          // copy gets a fresh id
        cout << "copy c.id=" << c.getId() << " alive=" << Widget::aliveCount() << "\n";
        b = c;                                 // assignment keeps b's id
        cout << "after b = c, b.id=" << b.getId() << "\n";
    }
    cout << "after scope alive=" << Widget::aliveCount() << "\n";
}
